let captured=null;
const send=message=>chrome.runtime.sendMessage(message);
async function status(){const s=await send({type:'STATUS'});document.getElementById('connection').textContent=s.paired?'Connected as '+s.email:'Connect from ApplyFlow Settings in this browser.';document.getElementById('accept').hidden=!s.pendingEmail;if(s.pendingEmail)document.getElementById('accept').textContent='Connect as '+s.pendingEmail;document.getElementById('save').disabled=!s.paired;document.getElementById('autofill').disabled=!s.paired;}
document.getElementById('accept').addEventListener('click',async()=>{await send({type:'ACCEPT_PAIR'});await status();});
document.getElementById('disconnect').addEventListener('click',async()=>{await send({type:'UNPAIR'});await status();});
document.getElementById('capture').addEventListener('submit',async e=>{e.preventDefault();if(!captured)return;const button=document.getElementById('save');button.disabled=true;document.getElementById('status').textContent='Saving to the private Shadow queue…';try{const result=await send({type:'CAPTURE',capture:{...captured,title:document.getElementById('title').value,company:document.getElementById('company').value,text:document.getElementById('text').value}});if(!result.ok)throw new Error(result.error);document.getElementById('status').textContent='Saved. Shadow analysis queued. Open or refresh ApplyFlow to see it.';}catch(e){document.getElementById('status').textContent=e.message;}finally{button.disabled=false;}});
(async()=>{await status();try{const [tab]=await chrome.tabs.query({active:true,currentWindow:true});if(!tab?.id||!/^https:\/\//.test(tab.url||''))throw new Error('Open a public HTTPS job listing.');const [{result}]=await chrome.scripting.executeScript({target:{tabId:tab.id},func:()=>{
 let posting=null;function find(v,depth=0){if(!v||depth>8)return;if(Array.isArray(v)){for(const x of v)find(x,depth+1);}else if(typeof v==='object'){if([v['@type']].flat().includes('JobPosting'))posting=v;else if(v['@graph'])find(v['@graph'],depth+1);}}
 for(const el of document.querySelectorAll('script[type="application/ld+json"]')){try{find(JSON.parse(el.textContent));}catch{}if(posting)break;}
 const plain=html=>{const el=document.createElement('div');el.innerHTML=String(html||'');return el.textContent||'';};
 const area=document.querySelector('.jobs-description,.jobsearch-jobDescriptionText,[data-test="job-description"],#jobDescriptionText,main,article')||document.body;
 const text=posting?.description?plain(posting.description):area.innerText;
 const url=new URL(location.href);url.hash='';for(const key of [...url.searchParams.keys()])if(/^utm_|^(trk|trackingId|ref|refId|source)$/i.test(key))url.searchParams.delete(key);
 const host=url.hostname.toLowerCase(),ats=host.includes('greenhouse')?'Greenhouse':host.includes('lever.co')?'Lever':host.includes('myworkday')?'Workday (detection only)':host.includes('ashby')?'Ashby (detection only)':host.includes('icims')?'iCIMS (detection only)':host.includes('smartrecruiters')?'SmartRecruiters (detection only)':host.includes('teamtailor')?'Teamtailor (detection only)':'Unknown / source listing';
 return {url:url.href,title:posting?.title||document.querySelector('h1')?.innerText||document.title,company:posting?.hiringOrganization?.name||document.querySelector('[data-company-name],.jobsearch-InlineCompanyRating,.jobs-unified-top-card__company-name')?.textContent?.trim()||'',text:String(text||'').slice(0,50000),ats};
 }});captured=result;document.getElementById('title').value=result.title;document.getElementById('company').value=result.company;document.getElementById('text').value=result.text;document.getElementById('ats').textContent='Detected: '+result.ats;document.getElementById('url').textContent=result.url;}catch(e){document.getElementById('status').textContent=e.message;document.getElementById('save').disabled=true;}})();

document.getElementById('autofill').addEventListener('click',async()=>{const button=document.getElementById('autofill'),out=document.getElementById('fillStatus');button.disabled=true;try{const data=await send({type:'AUTOFILL_PROFILE'});if(!data.ok)throw new Error(data.error);const [tab]=await chrome.tabs.query({active:true,currentWindow:true});if(!tab?.id||!/^https:\/\//.test(tab.url||'')||(new URL(tab.url).hostname.endsWith('chatgpt.site')&&new URL(tab.url).pathname!=='/agent-sandbox.html'))throw new Error('Open an employer application form in this tab.');const results=await chrome.scripting.executeScript({target:{tabId:tab.id},func:applyFlowFill,args:[data.profile,data.answers]});const r=results[0].result;out.textContent=r.blocked?r.reason:r.filled.length+' fields filled. Review before submitting.\n'+(r.unanswered.length?'Needs your answer: '+r.unanswered.join(', '):'')+'\n'+r.skipped.join(', ')+(r.securityCheck?'\nComplete any site security check yourself.':'')+(r.frameCount?'\nSome form frames cannot be accessed. Open the employer form directly.':'')+(r.filled.length===0?'\nNo empty supported fields were filled. Check your saved profile and confirm first/last names above.':'');}catch(e){out.textContent=e.message;}finally{await status();}});

document.getElementById('saveNames').addEventListener('click',async()=>{const out=document.getElementById('fillStatus');try{const r=await send({type:'SAVE_NAMES',first_name:document.getElementById('firstName').value,last_name:document.getElementById('lastName').value});if(!r.ok)throw new Error(r.error);out.textContent='Names confirmed for this account. Click Autofill again.';}catch(e){out.textContent=e.message;}});
